driver.find_element(AppiumBy.ID,'com.arduia.expense:id/btn_save').click()
WebDriverWait(driver,8).until(lambda d: 'btn_save' not in d.page_source)
root=ET.fromstring(driver.page_source)
recent=[]
for card in root.iter():
 if card.attrib.get('resource-id')=='com.arduia.expense:id/cd_expense':
  vals={}
  for c in card.iter():
   rid=c.attrib.get('resource-id','')
   if rid.endswith('/tv_name'): vals['name']=c.attrib.get('text')
   elif rid.endswith('/tv_amount'): vals['amount']=c.attrib.get('text')
   elif rid.endswith('/tv_date'): vals['date']=c.attrib.get('text')
  if vals: recent.append(vals)
{'activity':driver.current_activity,'recent':recent[:5]}

